static bool cs_id_eq(const char *a, const char *b)
{
    if (!a || !b) return false;
    while (*a && *b) {
        char ca = *a, cb = *b;
        if (ca >= 'A' && ca <= 'Z') ca = (char)(ca - 'A' + 'a');
        if (cb >= 'A' && cb <= 'Z') cb = (char)(cb - 'A' + 'a');
        if (ca != cb) return false;
        a++; b++;
    }
    return *a == 0 && *b == 0;
}

const lv_image_dsc_t *cs_logo_get(const char *id)
{
    if (!id || !id[0]) return NULL;
    for (unsigned i = 0; i < sizeof(CS_LOGOS48) / sizeof(CS_LOGOS48[0]); i++)
        if (cs_id_eq(CS_LOGOS48[i].id, id)) return CS_LOGOS48[i].dsc;
    return NULL;
}

